 "හේතු ධර්මයන් සමඟ ඒකෝත්පාදාදී ලක්ෂණ නැත්තාවූ ධර්මයෝ \"හෙතුවිප්පයුත්තා\" නම් වේ.": "缺乏與諸根法一同生起等特徵的諸法，稱為“根不相應”（hetuvippayuttā）。",
 "අහේතුක දුකයට සමාන අර්ථයක් ඇත.": "其義與無因（ahetuka）二法相似。",
 "ඡන්දය හැර චෛතසික 12.": "12 個心所，除欲。",
 "රූප, වේදනා, සඤ්ඤා, සංඛාර, විඤ්ඤාණ.": "色、受、想、行、識。",
 "දුක්ඛ, නිරෝධ.": "苦、滅。",
 "මෙම දුකයෙන් බැහැර වන ධර්ම නොමැත.": "沒有被排除於此二法之外的法。",
 "හේතු ධර්මයන් සහ සහේතුක ධර්මයන් එකවර වන ධර්ම.": "既是根又是有因的諸法。",
 "හේතු නම් වූ ද සහේතුක වූ ද ධර්ම.": "既是根又是有因的諸法。",
 "මෝහ මූල දෙසිත්හි මෝහය හැර හේතු 6.": "6 個根，除兩個癡根心中的癡。",
 "මෙම පදයට අයත් ධර්මයන් පහත පරිදි වේ.": "屬於此術語的諸法如下。",
 "මෝහ මූල දෙසිත්හි මෝහය හැර ලෝභ, දෝස, අලෝභ, අදෝස, අමෝහ.": "貪、嗔、無貪、無嗔、無癡——除兩個癡根心中的癡。",
 "සංග්‍රහය පහත පරිදි වේ.": "攝類（saṅgaha）如下。",
 "සංස්කාරස්කන්ධය.": "行蘊。",
 "ධම්මායතනය.": "法處。",
 "ධම්මධාතුව.": "法界。",
 "හේතු 6.": "6 個根。",
 "සහේතුක වූද හේතු නොවන්නා වූ ධර්ම.": "有因（sahetuka）而又不是根的諸法。",
