 "ෂඩ්ද්වාරයෙන් වැගිරෙන බැවින් ලෝභ, දිට්ඨි, මෝහ යන ධර්ම \"ආසව\" නම් වේ.": "因為經由六門流出，貪、見與癡諸法稱為“漏”（āsava）。",
 "දෙවන ක්‍රමය - (භූමිතො ආභවග්ගං, ධම්මතො ආගොත්‍රභූං සවන්තී'ති = ආසවා). තෙවන ක්‍රමය - (චිරපාරිවාසියට්ඨෙන මදිරාදයො ආසවා වියා'ති = ආසවා). සතරවන ක්‍රමය - (ආයතිං සංසාරදුක්ඛං සවන්තී'ති = ආසවා).": "第二種方法——（bhūmito ābhavaggaṃ, dhammato āgotrabhuṃ savantī'ti = āsavā）。第三種方法——（cirapārivāsiyaṭṭhena madirādayo āsavā viyā'ti = āsavā）。第四種方法——（āyatiṃ saṃsāradukkhaṃ savantī'ti = āsavā）。",
 "කාමාශ්‍රවය හා භවාශ්‍රවය ලෝභ චෛතසිකය යි.": "欲漏（kāmāsava）與有漏（bhavāsava）是貪心所。",
 "දිට්ඨාශ්‍රවය දිට්ඨි චෛතසිකය යි.": "見漏（diṭṭhāsava）是見心所。",
 "අවිජ්ජාශ්‍රවය මෝහ චෛතසිකය යි.": "無明漏（avijjāsava）是癡心所。",
 "එකම සංස්කාරස්කන්ධයකි.": "它是單一的行蘊。",
 "එකම ධම්මායතනයකි.": "它是單一的法處。",
 "එකම ධම්මධාතුවකි.": "它是單一的法界。",
 "දිට්ඨි මෝහ දෙක දුක්ඛ සත්‍යයකි, ලෝභය සමුදය සත්‍යයකි.": "見與癡是苦諦；貪是集諦。",
 "ලෝභ, දිට්ඨි, මෝහ නම් වූ චෛතසික තිදෙනා ලැබෙන්නාහ.": "得到稱為貪、見與癡的三個心所。",
 "ආසව චෛතසික 3": "3 個漏心所",
 "දිට්ඨි මෝහ දෙක": "見與癡",
 "ලෝභය": "貪",
 "ආශ්‍රව නම් නොවන්නා වූ ධර්ම ය.": "不稱為漏的諸法。",
 "ආශ්‍රව ධර්ම තුන හැර සෙසු සියලු පරමාර්ථ ධර්ම මෙයට අයත් වේ.": "除三個漏法之外的其餘一切究竟法，屬於此。",
 "ආශ්‍රව ධර්ම තුන වර්ජිත චෛතසික 49.": "49 個心所，除三個漏法。",
 "දුක්ඛ, නිරෝධ, මාර්ග.": "苦、滅、道。",
 "එකුන් අනූ චිත්තය ද, ආශ්‍රව ධර්ම තුන වර්ජිත එකුන් පණස් චෛතසිකය ද, අටවිසි රූපය ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到 89 個心、除三個漏法之外的 49 個心所、28 種色與涅槃。",
 "චෛතසික 49 + රූප 28 + නිර්වාණය": "49 個心所＋28 種色＋涅槃",
 "ලෞකික සිත් 81 + චෛතසික 48 + රූප 28": "81 個世間心＋48 個心所＋28 種色",
 "අරමුණු වීම් වශයෙන් ආශ්‍රවයන් සමඟ පවත්නා ධර්ම \"සාසව\" නම් වේ.": "以作為漏之所緣的方式與諸漏一同存在的諸法，稱為“有漏”（sāsava）。",
 "ආශ්‍රව සමඟ මිශ්‍ර වූ බව ද ආශ්‍රවයන් හට අරමුණු වූ බව ද ගොදුරු වූ බව එයින් කියැවේ. ලෞකික චිත්ත චෛතසික රූප ධර්ම සියල්ල ම ආශ්‍රව ධර්මයන් හට අරමුණු වන බැවින් \"සාසව\" නම් වෙයි.": "這顯示它們與諸漏混合，並且是諸漏的所緣與所依。因為一切世間的心、心所與色法都是漏法的所緣，所以稱為“有漏”。",
 "ලෞකික සිත් එක් අසූව ද, තත්සම්ප්‍රයුක්ත චෛතසික දෙපණස ද, අටවිසි රූපය ද ලැබෙන්නාහ.": "得到 81 個世間心、52 個相應心所與 28 種色。",
 "සම්ප්‍රයුක්ත වශයෙන් හෝ අරමුණු කිරීම් වශයෙන් හෝ ආශ්‍රව නොමැති ධර්ම \"අනාසව\" නම් වේ.": "無論是由相應還是由被取為所緣，都沒有漏的諸法，稱為“無漏”（anāsava）。",
 "න + ආසවා = අනාසවා; \"න\" යන නිපාතයට \"අන්\" ආදේශ වී සන්ධි වූ විට අනාසව පදය සෑදේ.": "na＋āsavā＝anāsavā；當不變詞“na”被替換為“an”並作連音（sandhi）時，形成 anāsava 一詞。",
