 "ආශ්‍රව ධර්මයන් සමඟ ඒකෝත්පාදාදී වශයෙන් සතර සම්ප්‍රයෝග ලක්ෂණයෙන් මිශ්‍ර වූ ධර්ම \"ආසව සම්පයුත්ත\" නම් වේ.": "以俱生等四種相應特徵與諸漏法混合的諸法，稱為“漏相應”（āsavasampayutta）。",
 "ලෝභ මූල සිත්වල ඇති ආශ්‍රව ධර්මයන් එකිනෙකාට සම්ප්‍රයුක්ත වන බැවින් \"ආසව සම්පයුත්ත\" වේ.": "因為貪根心中的諸漏法彼此相應，所以是“漏相應”。",
 "ලෝභ මූල 8, දෝස මූල 2, මෝහ මූල 2.": "8 個貪根心、2 個嗔根心、2 個癡根心。",
 "ද්වේෂ මූල මෝහ මූල දෙසිත්හි මෝහය හැර චෛතසික 27.": "兩個嗔根心與癡根心中除癡之外的 27 個心所。",
