 "අකුසල් සිත් 12 + චෛතසික 26": "12 個不善心＋26 個心所",
 "ආශ්‍රව ධර්මයන් සමඟ මිශ්‍ර නොවූ ධර්ම \"ආසව විප්පයුත්ත\" නම් වේ.": "不與諸漏法混合的諸法，稱為“漏不相應”（āsavavippayutta）。",
