 "ආශ්‍රව නම් වූ ද ආශ්‍රවයන් හට අරමුණු නම් වූ ද ධර්ම.": "既稱為漏、又是漏之所緣的諸法。",
 "ලෝභ දිට්ඨි මෝහ නම් වූ ආශ්‍රව ධර්ම තිදෙන ලැබෙන්නාහ.": "得到稱為貪、見與癡的三個漏法。",
