 "ලෞකික සිත් එක් අසූව ද, ආශ්‍රව ධර්ම වර්ජිත එකුන් පණස් චෛතසිකය ද, අටවිසි රූපය ද ලැබෙන්නාහ.": "得到 81 個世間心、除漏法之外的 49 個心所與 28 種色。",
