 "දොළොස් අකුසල් සිත් වර්ජිත සත්සැත්තෑ චිත්තය ද, තත්සම්ප්‍රයුක්ත චෛතසික අටතිස ද, උද්ධච්ච සහගත සිතෙහි මෝහය ද, අටවිසි රූපය ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到除 12 個不善心之外的 77 個心、38 個相應心所、與掉舉俱的心中的癡、28 種色與涅槃。",
