 "ලෝභ, දෝස, මාන, දිට්ඨි, විචිකිච්ඡා, ඉස්සා, මච්ඡරිය, මෝහ.": "貪、嗔、慢、見、疑、嫉、慳、癡。",
 "සංයෝජන ධර්ම අට දෙන ලැබෙන්නාහ.": "得到八個結法。",
 "සංයෝජන ධර්මයන්ට අරමුණු වූ ද එහෙත් සංයෝජන නම් නොවූ ධර්ම.": "是結法之所緣、但本身不稱為結的諸法。",
 "සංයෝජන ධර්ම වර්ජිත චෛතසික 44.": "除結法之外的 44 個心所。",
 "ලෞකික සිත් එක් අසූව ද, සංයෝජන ධර්ම වර්ජිත සූසාලිස් චෛතසිකය ද, අටවිසි රූපය ද ලැබෙන්නාහ.": "得到 81 個世間心、除結法之外的 44 個心所與 28 種色。",
 "චෛතසික 44 + රූප 28": "44 個心所＋28 種色",
 "ලෞකික සිත් 81 + චෛතසික 42 + රූප 28": "81 個世間心＋42 個心所＋28 種色",
 "අසංයෝජනියා පදයේ ස්වරූපාර්ථ: ලෝකෝත්තර සිත් 8, චෛතසික 36, නිර්වාණය.": "“asaṃyojanīyā”一詞的究竟義：8 個出世間心、36 個心所、涅槃。",
