 "උද්ධච්ච සිතෙහි මෝහය වර්ජිත සංයෝජන ධර්ම අටදෙන ලැබෙන්නාහ.": "得到八個結法，除掉舉心中的癡。",
 "සංයෝජන ධර්මයන් සමඟ සම්ප්‍රයුක්ත වූ එහෙත් සංයෝජන නම් නොවූ ධර්ම.": "與結法相應、但本身不稱為結的諸法。",
 "සංයෝජන ධර්ම වර්ජිත චෛතසික 19.": "除結法之外的 19 個心所。",
 "අකුසල් සිත් දොළොස ද, සංයෝජන ධර්ම වර්ජිත එකුන් විස්ස චෛතසික ද ලැබෙන්නාහ.": "得到 12 個不善心與除結法之外的 19 個心所。",
 "සංඛාර චෛතසික 17": "17 個行心所",
 "චෛතසික 19": "19 個心所",
 "අකුසල් සිත් 12 + චෛතසික 19": "12 個不善心＋19 個心所",
 "සංයෝජනවිප්පයුත්තා පදයේ ස්වරූපාර්ථ: කුසල විපාක ක්‍රියා සිත් 77, චෛතසික 38, උද්ධච්ච සිතේ මෝහය, රූප 28, නිර්වාණය.": "“saṃyojanavippayuttā”一詞的究竟義：77 個善、果報與唯作心、38 個心所、掉舉心中的癡、28 種色、涅槃。",
 "සංයෝජන ධර්මයන් සමඟ විප්‍රයුක්ත වූ ද එහෙත් සංයෝජනයන්ට අරමුණු වූ ද ධර්ම.": "與結法不相應、但是結之所緣的諸法。",
 "ලෝභ මූල දෝස මූල අකුසල් සිත් දශය වර්ජිත ඉතිරි ලෞකික සිත් 69.": "其餘 69 個世間心，除十個貪根與嗔根不善心。",
 "උද්ධච්ච සිතේ මෝහය.": "掉舉心中的癡。",
 "අකුසල් සිත් දොළස වර්ජිත ලෞකික සිත් එකුන් සැත්තෑව ද, තත් සම්ප්‍රයුක්ත චෛතසික අටතිස ද උද්ධච්ච සහගත සිතෙහි මෝහය ද අටවිසි රූපය ද ලැබෙන්නාහ.": "得到除 12 個不善心之外的 69 個世間心、38 個相應心所、掉舉心中的癡與 28 種色。",
 "සංයෝජන ධර්මයන් සමඟ විප්‍රයුක්ත වූ ද සංයෝජනයන්ට අරමුණු නොවූ ද ධර්ම.": "與結法不相應、且不是結之所緣的諸法。",
 "ලෝකෝත්තර සිත් අට ද, තත් සම්ප්‍රයුක්ත චෛතසික සතිස ද නිර්වාණය ද ලැබෙන්නාහ.": "得到 8 個出世間心、36 個相應心所與涅槃。"
