 "ලෝකෝත්තර ධර්ම සියල්ල ම ඕඝයන්ට අරමුණු නොවන බැවින් \"අනෝඝනිය\" වේ.": "因為一切出世間法都不是暴流的所緣，所以是“不可暴流”（anoghanīya）。",
 "ඕඝ ධර්මයන් සමඟ ඒකෝත්පාදාදී සතර සම්ප්‍රයෝග ලක්ෂණයෙන් මිශ්‍ර වූ ධර්ම \"ඕඝ සම්පයුත්ත\" නම් වේ.": "以俱生等四種相應特徵與暴流法混合的諸法，稱為“暴流相應”（oghasampayutta）。",
