 "ද්වේෂ මූල මෝහ මූල සිත් සතරෙහි මෝහය වර්ජිත චෛතසික 27.": "四個嗔根與癡根心中除癡之外的 27 個心所。",
 "ඕඝ ධර්මයන් සමඟ මිශ්‍ර නොවූ ධර්ම \"ඕඝ විප්පයුත්ත\" නම් වේ.": "不與暴流法混合的諸法，稱為“暴流不相應”（oghavippayutta）。",
