 "ලෞකික විපාක සිත් දෙතිස්දෙන ද, තත් සම්ප්‍රයුක්ත වූ චෛතසික පන්තිස්දෙන ද, කර්මජ රූප විස්ස ද ලැබෙන්නාහ.": "得到 32 個世間果報心、35 個相應心所與 20 種業生色。",
 "ලෞකික විපාක සිත් 32": "32 個世間果報心",
 "චෛතසික 35 + කර්මජ රූප 20": "35 個心所＋20 種業生色",
 "තෘෂ්ණා දෘෂ්ටීන් විසින් ගන්නා ලද අරමුණක් අනුව, කර්ම ක්ලේශයන් විසින් ස්වකීය ඵලය වශයෙන් ළඟා කොට නො ගන්නා ලද්දා වූ ධර්මයෝ \"අනුපාදින්න\" නම් වේ.": "不以愛與邪見所取的所緣為基礎、而被業與煩惱取為自己之果的諸法，稱為“非被取”（anupādinna）。",
 "ලෞකික විපාක සිත් වර්ජිත සිත් 57, චෛතසික 52, චිත්තජ රූප 17, උතුජ රූප 15, ආහාරජ රූප 14, නිර්වාණය අනුපාදින්න වේ.": "除世間果報心之外的 57 個心、52 個心所、17 種心生色、15 種時節生色、14 種食生色與涅槃是非被取。",
 "ලෞකික විපාක සිත් වර්ජිත ඉතිරි සිත් සත්පණස.": "除世間果報心之外的其餘 57 個心。",
 "මනායතනය ඇතුළු ආයතන 7.": "包括意處在內的 7 處。",
 "ලෞකික විපාක සිත් වර්ජිත ඉතිරි සිත් සත්පණස ද, තත් සම්ප්‍රයුක්ත චෛතසික දෙපණස ද, චිත්තජ රූප සතළොස ද, උතුජ රූප පසළොස ද, ආහාරජ රූප තුදුස ද, නිර්වාණ ධාතුව ද ලැබෙන්නාහ.": "得到除世間果報心之外的其餘 57 個心、52 個相應心所、17 種心生色、15 種時節生色、14 種食生色與涅槃界。",
