MX_I18N.add({
 "ඉතිරි සිත් 57": "其餘 57 個心",
 "චෛතසික 52 + චිත්තජ රූප 17 + උතුජ රූප 15 + ආහාරජ රූප 14 + නිර්වාණය": "52 個心所＋17 種心生色＋15 種時節生色＋14 種食生色＋涅槃",
 "ඉතිරි සිත් 57 + චෛතසික 52 + චිත්තජ රූප 17 + උතුජ රූප 15 + ආහාරජ රූප 14": "其餘 57 個心＋52 個心所＋17 種心生色＋15 種時節生色＋14 種食生色",
 "මහන්තර දුකයේ ස්වරූපය": "大間二法（Mahantara Duka）的性質",
 "පරාමාස ගොච්ඡකයට අනතුරුව මහන්තර දුකය දේශනා කොට වදාළ සේක. මහන්තර දුක යනු මහත් + අන්තර + දුක යනුවෙන් පද බෙදාගත යුතු වේ. (අන්තරෙ ඨපිතා දුකා = අන්තරදුකා; මහන්තාච තෙ අන්තරදුකාචා'ති=මහන්තරදුකා). එක් දුකයක් සමඟ තවත් දුකයක් ශබ්ද සහ අර්ථ වශයෙන් සම්බන්ධ නොවී හුදු දුක භාවයෙන් (දුක සාම්‍යයෙන්) පමණක් වෙන වෙන ම තෝරා ගොච්ඡකයන්ගේ අන්තරයෙහි තබන ලද බැවින් ද, චූළන්තර දුකයට වඩා මහත් බැවින් ද \"මහන්තරදුක\" යැයි කියනු ලැබේ.": "佛陀宣說執取類之後，宣說了大間二法。將“Mahantara Duka”一詞分為“mahanta＋antara＋duka”。（Antare ṭhapitā dukā = antaradukā; mahantā ca te antaradukā cā'ti = mahantaradukā.）因為每個二法都是單獨挑出、僅憑其為二法（依二法的相似性）而安置於諸類之間，在詞與義上不與另一二法相連，並且因為它比小間二法更大，所以稱為“大間二法”。",
 "මහන්තර දුකයේ දුක 14": "大間二法的 14 個二法",
 "මහන්තර දුකය ද සාරම්මණ දුකය, චිත්ත දුකය, චේතසික දුකය, චිත්තසම්පයුත්ත දුකය, චිත්තසංසට්ඨ දුකය, චිත්තසමුට්ඨාන දුකය, චිත්තසහභූ දුකය, චිත්තානුපරිවත්ති දුකය, චිත්තසංසට්ඨසමුට්ඨාන දුකය, චිත්තසංසට්ඨසමුට්ඨානසහභූ දුකය, චිත්තසංසට්ඨසමුට්ඨානානුපරිවත්ති දුකය, අජ්ඣත්තික දුකය, උපාදා දුකය, උපාදින්න දුකය යනුවෙන් තුදුස් වැදෑරුම් වන්නේය.": "大間二法有十四種：有所緣二法、心二法、心所二法、心相應二法、心和合二法、心等起二法、心俱生二法、隨心轉二法、心和合等起二法、心和合等起俱生二法、心和合等起隨轉二法、內二法、所造二法與被取二法。",
 "මම ය, මාගේ ය යැයි අරමුණු දැඩිකොට ගන්නා වූ ධර්මයෝ \"උපාදාන\" නම් වේ.": "把所緣牢固地執為“我”與“我所”的諸法，稱為“取”（upādāna）。",
 "කාමුපාදානා, දිට්ඨුපාදානා, සීලබ්බතුපාදානා, අත්තවාදුපාදානා යන උපාදාන 4කි. පරමාර්ථ ධර්මයන් වශයෙන් ලෝභ-දිට්ඨි චෛතසිකයන් \"උපාදාන\" නම් වේ.": "有四取：欲取（kāmupādāna）、見取（diṭṭhupādāna）、戒禁取（sīlabbatupādāna）與我語取（attavādupādāna）。就究竟法而言，貪與見心所稱為“取”。",
 "ලෝභ දිට්ඨි නම් වූ චෛතසික දෙදෙනා ලැබෙන්නාහ.": "得到稱為貪與見的兩個心所。",
 "උපාදාන චෛතසික 2": "2 個取心所",
 "මම ය, මාගේ ය යැයි දැඩිකොට නොගන්නා බැවින් උපාදාන නම් නොවූ ධර්ම ය.": "因不牢固地執為“我”與“我所”而不稱為取的諸法。",
 "ලෝභ, දිට්ඨි යන උපාදාන ධර්ම දෙක හැර සෙසු සියලු පරමාර්ථ ධර්ම මෙයට අයත් වේ.": "除貪與見兩個取法之外的其餘一切究竟法，屬於此。",
 "ලෝභ දිට්ඨි වර්ජිත චෛතසික 50.": "除貪與見的 50 個心所。",
 "එකුන් අනූ චිත්තය ද, ලෝභ දිට්ඨි වර්ජිත සමපණස් චෛතසිකය ද, අටවිසි රූපය ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到 89 個心、除貪與見之外的 50 個心所、28 種色與涅槃。",
 "චෛතසික 50 + රූප 28 + නිර්වාණය": "50 個心所＋28 種色＋涅槃",
 "තෘෂ්ණා දෘෂ්ටි නම් වූ උපාදානයන්ට අරමුණු වන්නා වූ ධර්ම ය.": "作為稱為愛與邪見之諸取的所緣的諸法。",
 "ලෞකික සිත් 81, චෛතසික 52, රූප 28 උපාදානිය වේ.": "81 個世間心、52 個心所與 28 種色是可取（upādāniya）。",
 "උපාදාන 4": "4 取",
 "උපාදානයන් හට අරමුණු නොවන්නා වූ ධර්ම ය.": "不是諸取之所緣的諸法。",
 "ලෝකෝත්තර සිත් 8, චෛතසික 36, නිර්වාණය අනුපාදානිය වේ.": "8 個出世間心、36 個心所與涅槃是非可取（anupādāniya）。",
 "උපාදානයන් සමග ඒකෝත්පාදාදී වශයෙන් මිශ්‍ර වූ ධර්ම \"උපාදාන සම්පයුත්ත\" නම් වේ.": "以俱生等方式與諸取混合的諸法，稱為“取相應”（upādānasampayutta）。",
 "දිට්ඨිගත සම්ප්‍රයුක්ත සිත් සතරෙහි ඇති ලෝභය සහ දිට්ඨිය යන උපාදාන ධර්ම දෙක \"උපාදානසම්ප්‍රයුක්ත\" වේ. දිට්ඨිගත විප්‍රයුක්ත සිත් සතරෙහි ඇති ලෝභය \"උපාදානවිප්‍රයුක්ත\" නම් වේ.": "四個與邪見相應的心中的貪與見兩個取法是“取相應”。四個與邪見不相應的心中的貪，稱為“取不相應”（upādānavippayutta）。",
 "ලෝභ මූල අකුසල් සිත් අට.": "八個貪根不善心。",
 "දෝස ඉස්සා මච්ඡරිය කුක්කුච්ච විචිකිච්ඡා සහ දිට්ඨිගත විප්පයුත්ත සිත් සතරෙහි ලෝභය වර්ජිත චෛතසික 22.": "22 個心所，除嗔、嫉、慳、惡作、疑與四個與邪見不相應之心中的貪。",
 "ලෝභ මූල අකුසල් සිත් අට ද, දෝස ඉස්සා මච්ඡරිය කුක්කුච්ච විචිකිච්ඡා සහ දිට්ඨිගත විප්පයුත්ත සිත් සතරෙහි ලෝභය ද, වර්ජිත චෛතසික දෙවිස්ස ද ලැබෙන්නාහ.": "得到八個貪根不善心，以及除嗔、嫉、慳、惡作、疑與四個與邪見不相應之心中的貪之外的 22 個心所。",
 "චෛතසික 22": "22 個心所",
 "අකුසල් සිත් 10 + චෛතසික 21": "10 個不善心＋21 個心所",
 "උපාදානයන් සමග සම්ප්‍රයුක්ත නොවූ ධර්ම \"උපාදාන විප්පයුත්ත\" නම් වේ.": "不與諸取相應的諸法，稱為“取不相應”（upādānavippayutta）。",
 "ද්වේෂ මූල සිත් 02, මෝහ මූල සිත් 02, කුසල සිත් 21, විපාක සිත් 36, ක්‍රියා සිත් 20, ලෝභ දිට්ඨි මාන හැර සෙසු චෛතසික 49, දිට්ඨිගත විප්‍රයුක්ත සිත් සතරෙහි ඇති ලෝභය, රූප 28, නිර්වාණය උපාදානවිප්පයුත්ත වේ.": "2 個嗔根心、2 個癡根心、21 個善心、36 個果報心、20 個唯作心、除貪、見與慢之外的 49 個心所、四個與邪見不相應之心中的貪、28 種色與涅槃是取不相應。",
 "ලෝභ මූල සිත් 8 වර්ජිත ඉතිරි සිත් 81.": "其餘 81 個心，除 8 個貪根心。",
 "ලෝභ දිට්ඨි මාන වර්ජිත චෛතසික 49.": "除貪、見與慢的 49 個心所。",
 "ලෝභ මූල සිත් වර්ජිත එක් අසූ චිත්තය ද, ලෝභ දිට්ඨි මාන වර්ජිත එකුන්පණස් චෛතසිකය ද, අටවිසි රූපය ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到除貪根心之外的 81 個心、除貪、見與慢之外的 49 個心所、28 種色與涅槃。",
 "විඤ්ඤාණක්න්ධෝ": "識蘊",
 "ඉතිරි සිත් 79": "其餘 79 個心",
 "ඉතිරි සිත් 79 + චෛතසික 49 + රූප 28": "其餘 79 個心＋49 個心所＋28 種色",
 "දිට්ඨි විප්පයුත්ත සිත් 4 හි ලෝභය": "4 個與邪見不相應之心中的貪",
 "උපාදාන නම් වූ ද උපාදානයන් හට අරමුණු වූ ද ධර්ම.": "既稱為取、又是諸取之所緣的諸法。",
 "ලෝභ දිට්ඨි නම් වූ චෛතසික දෙක ලැබෙන්නාහ.": "得到稱為貪與見的兩個心所。",
 "උපාදානයන්ට අරමුණු වන්නා වූ උපාදාන නම් නොවූ ධර්ම.": "是諸取之所緣、但本身不稱為取的諸法。",
 "ලෝභ දිට්ඨි වර්ජිත චෛතසික සමපණස.": "除貪與見的 50 個心所。",
 "ලෞකික සිත් එක් අසූව ද, ලෝභ දිට්ඨි වර්ජිත චෛතසික සමපණස ද, අටවිසි රූපය ද ලැබෙන්නාහ.": "得到 81 個世間心、除貪與見之外的 50 個心所與 28 種色。",
 "චෛතසික 50 + රූප 28": "50 個心所＋28 種色",
 "අනුපාදානියා පදයේ ස්වරූපාර්ථ: ලෝකෝත්තර සිත් 8, චෛතසික 36, නිර්වාණය.": "“anupādāniyā”一詞的究竟義：8 個出世間心、36 個心所、涅槃。",
 "උපාදාන නම් වූ ද උපාදානයන් සමග සම්ප්‍රයුක්ත වූ ද ධර්ම.": "既稱為取、又與諸取相應的諸法。",
 "දිට්ඨිගත සම්ප්‍රයුක්ත සිත් සතරෙහි වූ ලෝභ දිට්ඨි නම් වූ උපාදාන ධර්මයෝ ලැබෙන්නාහ.": "得到四個與邪見相應之心中稱為貪與見的取法。",
 "උපාදානයන් සමග සම්ප්‍රයුක්ත වූ එහෙත් උපාදාන නම් නොවූ ධර්ම.": "與諸取相應、但本身不稱為取的諸法。",
 "ලෝභ දිට්ඨි වර්ජිත චෛතසික සමවිස්ස.": "除貪與見的 20 個心所。",
 "ලෝභ මූල සිත් අට ද, ලෝභ දිට්ඨි වර්ජිත චෛතසික සමවිස්ස ද ලැබෙන්නාහ.": "得到八個貪根心與除貪與見之外的 20 個心所。",
 "සංඛාර චෛතසික 18": "18 個行心所",
 "ලෝභ මූල සිත් 8": "8 個貪根心",
 "ලෝභ මූල සිත් 8 + චෛතසික 19": "8 個貪根心＋19 個心所",
 "උපාදානවිප්පයුත්තා පදයේ ස්වරූපාර්ථ: ලෝභ මූල සිත් වර්ජිත 81, චෛතසික 49, දි.වි.4 ලෝභය, රූප 28, නිර්වාණය.": "“upādānavippayuttā”一詞的究竟義：除貪根心之外的 81 個心、49 個心所、4 個與邪見不相應之心中的貪、28 種色、涅槃。",
 "උපාදානයන් සමග විප්‍රයුත්ත වූ ද උපාදානයන්ට අරමුණු වූ ද ධර්ම.": "與諸取不相應、但是諸取之所緣的諸法。",
 "ද්වේෂ මූල 2, මෝහ මූල 2, ලෞකික කුසල් 17, විපාක 32, ක්‍රියා 20.": "2 個嗔根心、2 個癡根心、17 個世間善心、32 個果報心、20 個唯作心。",
 "ද්වේෂ මූල සිත් දෙක ද, මෝහ මූල සිත් දෙක ද, ලෞකික කුසල් විපාක ක්‍රියා සිත් සැටනවය ද, ලෝභ දිට්ඨි මාන වර්ජිත චෛතසික සතළිස්නවය ද, දිට්ඨි විප්පයුත්ත සිත්වල ලෝභය ද, අටවිසි රූපය ද ලැබෙන්නාහ.": "得到 2 個嗔根心、2 個癡根心、69 個世間善、果報與唯作心、除貪、見與慢之外的 49 個心所、與邪見不相應之心中的貪，以及 28 種色。",
 "ඉතිරි සිත් 73": "其餘 73 個心",
 "ඉතිරි සිත් 73 + චෛතසික 49 + රූප 28": "其餘 73 個心＋49 個心所＋28 種色",
 "උපාදානයන් සමග විප්‍රයුක්ත වූ ද උපාදානයන්ට අරමුණු නොවූ ද ධර්ම.": "與諸取不相應、且不是諸取之所緣的諸法。",
 "ලෝකෝත්තර සිත් අට ද, තත් සම්ප්‍රයුක්ත චෛතසික සතිස ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到 8 個出世間心、36 個相應心所與涅槃。",
 "උපාදානසම්පයුත්තා පදයේ ස්වරූපාර්ථ: ලෝභ මූල සිත් 8, ලෝභ දිට්ඨි වර්ජිත චෛතසික සමවිස්ස.": "“upādānasampayuttā”一詞的究竟義：8 個貪根心、除貪與見的 20 個心所。",
 "උපාදාන ගොච්ඡකයේ ස්වරූපය": "取類（Upādāna Gocchaka）的性質",
 "මහන්තර දුකයට අනතුරුව උපාදාන ගොච්ඡකය දේශනා කොට වදාළ සේක. එය ද උපාදාන දුකය, උපාදානිය දුකය, උපාදාන සම්පයුත්ත දුකය, උපාදාන උපාදානිය දුකය, උපාදාන උපාදානසම්පයුත්ත දුකය, උපාදානවිප්පයුත්ත උපාදානිය දුකය යනුවෙන් සය වැදැරුම් වන්නේය.": "佛陀宣說大間二法之後，宣說了取類。它有六種：取二法、可取二法、取相應二法、取可取二法、取取相應二法與取不相應可取二法。",
 "උපාදාන නිරුක්තිය": "取（upādāna）的詞源",
 "උපාදාන - (උපාදියන්තීති - උපාදානා). මම ය, මාගේ ය යැයි අරමුණු දැඩිකොට ගන්නා වූ ධර්මයෝ \"උපාදාන\" නම් වේ. (කාමුපාදානා, දිට්ඨුපාදානා, සීලබ්බතුපාදානා, අත්තවාදුපාදානා.)": "Upādāna——（upādiyantī'ti = upādānā）。把所緣牢固地執為“我”與“我所”的諸法，稱為“取”（upādāna）。（Kāmupādāna, diṭṭhupādāna, sīlabbatupādāna, attavādupādāna.）",
 "උපාදාන ගොච්ඡකය - මිශ්‍රක දුකයන්": "取類——混合二法",
 "\"ඛො පන\" යන සවන දුකයෙහි අධික පදයාගේ අධිකාර්ථ වශයෙන් උපාදනා චෙව ධම්මා උපාදාන විප්පයුත්තාච උපාදාන විප්පයුත්තා චෙව ධම්මා නොච උපාදානා යන දුකයද, උපාදාන විප්පයුත්තා ධම්මා උපාදානීයාපි, අනුපාදානීයාපි යන දුකයද, උපාදානා ධම්මා උපාදාන සම්පයුත්තාපි, උපාදාන විප්පයුත්තාපි යන දුකයද, නො උපාදාන ධම්මා උපාදාන සම්පයුත්තාපි උපාදාන විප්පයුත්තාපි යන දුකයද වශයෙන් මිශ්‍රක දුකයෝ ලැබිය යුත්තාහ.": "依第七個二法中多出的“kho pana”一詞的附加含義，混合二法應得如下：二法“upādānā ceva dhammā upādānavippayuttā ca; upādānavippayuttā ceva dhammā no ca upādānā”；二法“upādānavippayuttā dhammā upādānīyāpi, anupādānīyāpi”；二法“upādānā dhammā upādānasampayuttāpi, upādānavippayuttāpi”；以及二法“no upādānā dhammā upādānasampayuttāpi, upādānavippayuttāpi”。",
 "අකුශල කර්ම සිදු කෙරෙන කල්හි ද, එහි විපාකය අපායාදියෙහි විඳින කල්හි ද, සිත් සතන් දවන තවන උපතාපන හිංසන පීඩන කරවන ධර්මයන් \"කිලෙස\" නම් වේ.": "在造不善業之時、以及在惡趣等中受其果報之時，焚燒、灼熱、折磨、擾亂並壓迫心的諸法，稱為“煩惱”（kilesa）。",
 "දෙවන ක්‍රමය - (සංකිලිස්සති එතෙනා'ති = කිලෙසා). එයින් සිත දූෂ්‍ය කරන බැවින් ලෝභ ආදී ධර්මයන් \"කිලෙස\" නම් වේ.": "第二種方法——（saṃkilissati etenā'ti = kilesā）。因為染汙心，貪等稱為“煩惱”（kilesa）。",
 "මාන චෛතසිකය.": "慢心所。",
 "විචිකිච්ඡා චෛතසිකය.": "疑心所。",
 "ථීන චෛතසිකය.": "昏沉心所。",
 "උද්ධච්ච චෛතසිකය.": "掉舉心所。",
 "ලෝභ - දෝස - මෝහ - මාන - දිට්ඨි - විචිකිච්ඡා - ථීන - උද්ධච්ච - අහිරික - අනොත්තප්ප යන ක්ලේශ වස්තු නම් වූ චෛතසික දස දෙනා ලැබෙන්නාහ.": "得到稱為煩惱之處的十個心所：貪、嗔、癡、慢、見、疑、昏沉、掉舉、無慚、無愧。",
 "කිලෙස චෛතසික 10": "10 個煩惱心所",
 "සන්තානය නොකෙලෙසන බැවින් කෙලෙස් නම් නොවූ ධර්ම ය.": "因不染汙相續而不是煩惱的諸法。",
 "දශ ක්ලේශ වස්තු හැර සෙසු සියලු පරමාර්ථ ධර්ම මෙයට අයත් වේ.": "除十煩惱處之外的其餘一切究竟法，屬於此。",
 "දශ කිලෙස් වර්ජිත දෙසාළිස් චෛතසිකය.": "除十煩惱的 42 個心所。",
 "එකුන් අනු චිත්තය ද, දශ කිලෙස් වර්ජිත දෙසාළිස් චෛතසිකය ද, අටවිසි රූපය ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到 89 個心、除十煩惱之外的 42 個心所、28 種色與涅槃。",
 "සංඛාර චෛතසික 40": "40 個行心所"
}, 'zh-Hant');
