 "ලෞකික සිත් 81 + චෛතසික 40 + රූප 28": "81 個世間心＋40 個心所＋28 種色",
 "කෙලෙසුන් හට අරමුණු වන්නා වූ නොහොත් කෙලෙසුන්ට ගොදුරු වන්නා වූ ධර්ම ය.": "作為煩惱之所緣的諸法，即作為煩惱之所依的諸法。",
 "සියලු සාසවා, සංයොජනීයා ආදියෙහි මෙන් ලෞකික ධර්ම මීට අයත් වේ.": "如同一切有漏、可結等二法，世間諸法屬於此。",
 "කිලෙස 10": "10 煩惱",
 "කෙලෙසුන් හට අරමුණු නොවන්නා වූ කෙලෙසුන්ට ගොදුරු නොවන්නා වූ ධර්ම ය.": "不是煩惱之所緣、不是煩惱之所依的諸法。",
 "ලෝකෝත්තර සිත් 8, චෛතසික 36, නිර්වාණය අසංකිලෙසික වේ.": "8 個出世間心、36 個心所與涅槃是非可染汙（asaṃkilesika）。",
 "කෙලෙසුන් විසින් කෙලෙසන ලද්දා වූ ධර්ම ය.": "被煩惱所染汙的諸法。",
 "අකුසල් සිත් 12, චෛතසික 27 සංකිලිට්ඨ වේ.": "12 個不善心與 27 個心所是染汙（saṃkiliṭṭha）。",
