 "ද්වේෂ මූල සිත් දෙකෙහි සහ මෝහ මූල සිත් දෙකෙහි ඇති මෝහය \"ඕඝ විප්පයුත්ත\" වේ.": "兩個嗔根心與兩個癡根心中的癡是“暴流不相應”（oghavippayutta）。",
 "ලෞකික සිත් 81, ඕඝ ධර්ම වර්ජිත එකුන්පණස් චෛතසිකය, රූප 28.": "81 個世間心、除暴流法的 49 個心所、28 種色。",
