 "ලෝභ, දිට්ඨි, මෝහ යන යෝග ධර්ම 3.": "3 個軛法：貪、見、癡。",
 "කාමයෝගෝ, භවයෝගෝ, දිට්ඨියෝගෝ, අවිජ්ජායෝගෝ යන යෝග 4කි. කාමයෝගය හා භවයෝගය ලෝභය යි; දිට්ඨියෝගය දිට්ඨිය යි; අවිජ්ජායෝගය මෝහය යි.": "有四軛：欲軛（kāmayoga）、有軛（bhavayoga）、見軛（diṭṭhiyoga）與無明軛（avijjāyoga）。欲軛與有軛是貪；見軛是見；無明軛是癡。",
 "සිත් 89, යෝග ධර්ම තුන වර්ජිත චෛතසික 49, රූප 28, නිර්වාණය.": "89 個心、除三個軛法的 49 個心所、28 種色、涅槃。",
 "ලෝභ, දිට්ඨි, මෝහ යන යෝග ධර්ම තුන හැර සෙසු සියලු පරමාර්ථ ධර්ම මෙම පදයට අයත් වේ.": "除貪、見、癡三個軛法之外的一切究竟法屬於此術語。",
