 "පරමාර්ථ ධර්මයන් වශයෙන් ලෝභ, ද්වේෂ, මෝහ, මාන, දිට්ඨි, විචිකිච්ඡා, ථින, උද්ධච්ච, අහිරික, අනොත්තප්ප යන චෛතසිකයන් දසය \"කිලෙස\" නම් වේ.": "就究竟法而言，貪、嗔、癡、慢、見、疑、昏沉、掉舉、無慚與無愧十個心所稱為“煩惱”（kilesa）。",
