 "න දස්සනේන පහාතබ්බහේතුකා ධම්මා": "Na dassanena pahātabbahetukā dhammā",
 "සෝවාන් මාර්ගයෙන් ම ප්‍රහාණය වන්නා වූ ධර්මයන් වර්ජිත කොට, අපායගාමී ශක්තියෙන් ද තොර වූ දිට්ඨිගත විප්‍රයුක්ත සිත් 4, දෝස මූල දෙසිත, සෝවාන් මගින් ප්‍රහාණය නොවන උද්ධච්ච සහගත සිත, දිට්ඨි විචිකිච්ඡා වර්ජිත සත්විසි චෛතසිකය, විචිකිච්ඡා සහගත සිතෙහි මෝහය, අවශේෂ සත් සැත්තෑ චිත්තය, අටතිස් චෛතසිකය, රූප 28, නිර්වාණය.": "除預流道本身所斷之法外：4 個與邪見不相應、也無導致惡趣之力的心；2 個嗔根心；不為預流道所斷的掉舉心；除邪見與疑之外的 27 個心所；疑相應心中的癡；其餘的 77 個心；38 個心所；28 種色；涅槃。",
 "විචිකිච්ඡා සහගත සිතෙහි මෝහය": "疑相應心中的癡",
 "භාවනාය පහාතබ්බහේතුකා දුකය": "修所斷因二法（Bhāvanāya Pahātabbahetukā Duka）",
 "භාවනාය පහාතබ්බහේතුකා ධම්මා - න භාවනාය පහාතබ්බහේතුකා ධම්මාති": "Bhāvanāya pahātabbahetukā dhammā – na bhāvanāya pahātabbahetukā dhammāti",
 "භාවනාය පහාතබ්බහේතුකා ධම්මා": "Bhāvanāya pahātabbahetukā dhammā",
 "සකදාගාමි මාර්ගයෙන් තුනී කිරීම වශයෙන් ප්‍රහාණය කටයුතු වූ ඖදාරික දිට්ඨිගත විප්‍රයුක්ත සිත් 4, ඖදාරික ද්වේෂ මූල දෙසිත, අනාගාමී මාර්ගයෙන් නිරවශේෂව ප්‍රහාණය කටයුතු වූ කාමරාගයෙන් යුක්ත දිට්ඨිගත විප්‍රයුක්ත සිත් 4, ද්වේෂ මූල දෙසිත, අර්හත් මාර්ගයෙන් නිරවශේෂව ප්‍රහාණය කටයුතු වූ රූපරාග අරූපරාග මාන උද්ධච්ච අවිජ්ජාවන් සමඟ යෙදුනා වූ දිට්ඨිගත විප්‍රයුක්ත සිත් 4, උද්ධච්ච සහගත සිත, දිට්ඨි විචිකිච්ඡාවන් හා උද්ධච්ච සිතෙහි මෝහය වර්ජිත පස්විසි චෛතසික.": "應由一來道削弱而斷的 4 個與邪見不相應的粗心；2 個粗的嗔根心；應由不還道完全斷除的、與欲貪相應而與邪見不相應的 4 個心；2 個嗔根心；應由阿羅漢道完全斷除的、與色有愛、無色有愛、慢、掉舉及無明相應而與邪見不相應的 4 個心；掉舉心；以及除邪見、疑與掉舉心中的癡之外的 25 個心所。",
 "භාවනාය පහාතබ්බහෙතුකා": "bhāvanāya pahātabbahetukā",
 "න භාවනාය පහාතබ්බහේතුකා ධම්මා": "Na bhāvanāya pahātabbahetukā dhammā",
 "සෝවාන් මගින් ම ප්‍රහාණය කටයුතු වන දිට්ඨිගත සම්ප්‍රයුක්ත සිත් 4, විචිකිච්ඡා සහගත සිත, සෝවාන් මගින් අනේකාන්තයෙන් ප්‍රහාණය කටයුතු වූ අපායගාමී ශක්තියෙන් යුක්ත දිට්ඨිගත විප්‍රයුක්ත සිත් 4, ද්වේෂ මූල දෙසිත, චෛතසික සත්විස්ස, දොළොස් අකුසල සිත් වර්ජිත අවශේෂ සත්සැත්තෑ චිත්තය, අටතිස් චෛතසිකය, උද්ධච්ච සහගත සිතෙහි මෝහය, රූප 28, නිර්වාණය.": "應僅由預流道斷除的 4 個邪見相應心；疑相應心；應由預流道以非專屬方式斷除的、4 個與邪見不相應而具有導致惡趣之力的心；2 個嗔根心；27 個心所；除 12 個不善心之外其餘的 77 個心；38 個心所；掉舉心中的癡；28 種色；涅槃。",
 "සවිතක්කා දුකය": "有尋二法（Savitakkā Duka）",
 "සවිතක්කා ධම්මා - අවිතක්කා ධම්මාති": "Savitakkā dhammā – avitakkā dhammāti",
 "සවිතක්කා ධම්මා": "Savitakkā dhammā",
 "සවිතර්ක සිත් 55, විතර්ක වර්ජිත චෛතසික 51.": "55 個有尋（vitakka）心；除尋之外的 51 個心所。",
 "අවිතක්කා ධම්මා": "Avitakkā dhammā",
 "අවිතර්ක සිත් 66, විතර්ක වර්ජිත තත් සම්ප්‍රයුක්ත චෛතසික 37, රූප 28, නිර්වාණය, සවිතර්ක සිත් පස්පණසෙහි විතර්ක පස්පණස.": "66 個無尋心；37 個相應心所（除尋）；28 種色；涅槃；以及 55 個有尋心中的 55 個尋。",
 "සවිචාරා දුකය": "有伺二法（Savicārā Duka）",
 "සවිචාරා ධම්මා - අවිචාරා ධම්මාති": "Savicārā dhammā – avicārā dhammāti",
 "සවිචාරා ධම්මා": "Savicārā dhammā",
 "සවිචාර සිත් සසැට දෙනා, විචාර වර්ජිත චෛතසික එක්පණස.": "66 個有伺（vicāra）心；除伺之外的 51 個心所。",
 "අවිචාරා ධම්මා": "Avicārā dhammā",
 "අවිචාර සිත් පස්පණස, විතර්ක විචාර වර්ජිත චෛතසික සතිස, සවිචාර සිත් සසැටෙහි විචාර චෛතසික සසැට දෙනා, රූප 28, නිර්වාණය.": "55 個無伺心；36 個心所（除尋與伺）；66 個有伺心中的 66 個伺心所；28 種色；涅槃。",
 "සප්පීතිකා දුකය": "有喜二法（Sappītikā Duka）",
 "සප්පීතිකා ධම්මා - අප්පීතිකා ධම්මාති": "Sappītikā dhammā – appītikā dhammāti",
 "සප්පීතිකා ධම්මා": "Sappītikā dhammā",
 "සප්පීතික සිත් එක්පණස, ප්‍රීති දෝස ඉස්සා මච්ඡරිය කුක්කුච්ච විචිකිච්ඡා වර්ජිත චෛතසික සසාළිස.": "51 個有喜（sappītika）心；46 個心所，除喜、嗔、嫉、慳、惡作與疑。",
 "අප්පීතිකා ධම්මා": "Appītikā dhammā",
 "අප්‍රීතික සිත් සමසැත්තෑව, තත් සම්ප්‍රයුක්ත එක් පණස් චෛතසිකය, සප්‍රීතික සිත් එක්පණසෙහි ප්‍රීති චෛතසික එක්පණස, අටවිසි රූපය, නිර්වාණ ධාතුව.": "70 個無喜心及其 51 個相應心所；51 個有喜心中的 51 個喜心所；28 種色；涅槃界。",
