 "උත්තරන්තී'ති = උත්තරා; සම උත්තරෙහී'ති = සඋත්තරා": "uttarantī'ti = uttarā; sama uttarehī'ti = sauttarā",
 "\"අනුත්තර\" යන පදයේ නිරුක්තිය පහත පරිදි විවරණය කළ හැක.": "“anuttara”（無上）一詞的詞源，可作如下說明。",
 "අනුත්තරා": "anuttarā",
 "නත්ථි උත්තරා තෙසන්'ති = අනුත්තරා": "natthi uttarā tesan'ti = anuttarā",
 "\"සරණ\" යන පදයේ නිරුක්තිය පහත පරිදි විවරණය කළ හැක.": "“saraṇa”（有諍）一詞的詞源，可作如下說明。",
 "සරණා": "saraṇā",
 "රණන්ති එතෙහී'ති = රණා; සහ රණෙහි යෙ වත්තන්තී'ති = සරණා": "raṇanti etehī'ti = raṇā; saha raṇehi ye vattantī'ti = saraṇā",
 "\"අරණ\" යන පදයේ නිරුක්තිය පහත පරිදි විවරණය කළ හැක.": "“araṇa”（無諍）一詞的詞源，可作如下說明。"
